// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address sender, address other) public {
        vm.assume(sender != address(0));
        vm.assume(other != address(0));
        vm.assume(sender != other);
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);
        vm.deal(other, amount);
        vm.prank(other);
        c.addToBalance{value: amount}();
        uint256 preBalSender = c.getBalance(sender);
        uint256 preBalOther = c.getBalance(other);
        uint256 preContractBal = address(c).balance;
        vm.deal(sender, amount);
        vm.prank(sender);
        c.addToBalance{value: amount}();
        uint256 postBalSender = c.getBalance(sender);
        uint256 postBalOther = c.getBalance(other);
        uint256 postContractBal = address(c).balance;
        assertTrue((postBalSender + postBalOther) == (preBalSender + preBalOther + amount));
    }
}
